65: // Reconcile is part of the main kubernetes reconciliation loop which aims to
66: // move the current state of the cluster closer to the desired state.
67: func (r *ComponentVersionReconciler) Reconcile(ctx context.Context, req ctrl.Request) (ctrl.Result, error) {
68: 	log := log.FromContext(ctx).WithName("ocm-component-version-reconcile")
69: 
70: 	log.Info("starting ocm component loop")
71: 
72: 	component := &v1alpha1.ComponentVersion{}
73: 	if err := r.Client.Get(ctx, req.NamespacedName, component); err != nil {
74: 		if apierrors.IsNotFound(err) {
75: 			return ctrl.Result{}, nil
76: 		}
77: 		return ctrl.Result{}, fmt.Errorf("failed to get component object: %w", err)
78: 	}
79: 
80: 	//TODO@souleb: reduce logging verbosity, use events instead. This will be easier to use logs
81: 	// for debugging and events for monitoring
82: 	log.V(4).Info("found component", "component", component)
83: 
84: 	// reconcile the version before calling reconcile func
85: 	update, version, err := r.checkVersion(ctx, component)
86: 	if err != nil {
87: 		return ctrl.Result{
88: 			RequeueAfter: component.GetRequeueAfter(),
89: 		}, fmt.Errorf("failed to check version: %w", err)
90: 	}
91: 
92: 	if !update {
93: 		log.V(4).Info("no new version which satisfies the semver constraint detected")
94: 		return ctrl.Result{
95: 			RequeueAfter: component.GetRequeueAfter(),
96: 		}, nil
97: 	}
98: 
99: 	log.Info("running verification of component")
100: 	ok, err := r.OCMClient.VerifyComponent(ctx, component, version)
101: 	if err != nil {
102: 		return ctrl.Result{
103: 			RequeueAfter: component.GetRequeueAfter(),
104: 		}, fmt.Errorf("failed to verify component: %w", err)
105: 	}
106: 
107: 	if !ok {
108: 		return ctrl.Result{
109: 			RequeueAfter: component.GetRequeueAfter(),
110: 		}, fmt.Errorf("attempted to verify component, but the digest didn't match")
111: 	}
112: 
113: 	return r.reconcile(ctx, component, version)
114: }
