116: func (r *ComponentVersionReconciler) checkVersion(ctx context.Context, obj *v1alpha1.ComponentVersion) (bool, string, error) {
117: 	log := log.FromContext(ctx).WithName("ocm-component-version-reconcile")
118: 
119: 	// get given semver constraint
120: 	constraint, err := semver.NewConstraint(obj.Spec.Version.Semver)
121: 	if err != nil {
122: 		return false, "", fmt.Errorf("failed to parse given semver constraint: %w", err)
123: 	}
124: 
125: 	// get current reconciled version
126: 	reconciledVersion := "0.0.0"
127: 	if obj.Status.ReconciledVersion != "" {
128: 		reconciledVersion = obj.Status.ReconciledVersion
129: 	}
130: 	current, err := semver.NewVersion(reconciledVersion)
131: 	if err != nil {
132: 		return false, "", fmt.Errorf("failed to parse reconciled version: %w", err)
133: 	}
134: 	log.V(4).Info("current reconciled version is", "reconciled", current.String())
135: 
136: 	// get latest available component version
137: 	latest, err := r.OCMClient.GetLatestComponentVersion(ctx, obj)
138: 	if err != nil {
139: 		return false, "", fmt.Errorf("failed to get latest component version: %w", err)
140: 	}
141: 	log.V(4).Info("got newest version from component", "version", latest)
142: 
143: 	latestSemver, err := semver.NewVersion(latest)
144: 	if err != nil {
145: 		return false, "", fmt.Errorf("failed to parse latest version: %w", err)
146: 	}
147: 
148: 	// compare given constraint and latest available version
149: 	valid, errs := constraint.Validate(latestSemver)
150: 	if !valid || len(errs) > 0 {
151: 		log.Info("version constraint check failed with the following problems", "errors", errs, "version", current)
152: 		return false, "", nil
153: 	}
154: 
155: 	return true, latest, nil
156: }
